/* The manuscript campaign, shared with existing 3D saves. */
(()=>{'use strict';
const siblings=['Elowen','Caelan','Maelis','Rowan','Thalia','Dain','Nerys','Orren'];
const voices=['I remain a healer. Finding my childhood does not erase the life I built.','I mended boots for a healer who turned out to be my sister. The silver thread was always there.','The song had a missing line. I can sing it now, but let me choose the stage.','I served the guard under a false name. My choices were still mine.','A song can be a map. I will mark safe crossings for the next lost traveler.','I remember the river stones—and the door someone locked at night. You waited for my answer before opening it.','I left white flowers outside Orren’s archive window. I think I knew before I remembered.','The book called us. The needles reveal names; they cannot force anyone home.'];
const mission=(title,district,room,setting,text,prompt,choices,answer,reveal,chapter)=>({title,district,room,setting,text,prompt,choices,answer,reveal,chapter});
const missions=[
mission('The book that knows your name','capital','archive','Royal Archive','A book opens by itself. Eight silver stitches shimmer across a blank page. Orren whispers: “Eight were lost beneath eight lanterns. Eight must choose their own road home.” A dated festival register points to Briar House.','Which lead can you verify first?',['The dated Briar House register','A rumor about a dragon','An unsigned market poster'],0,'The register bears an authentic gatekeeper’s seal. Briar House is no longer a rumor. Somewhere, eight grown children are living under borrowed names.',4),
mission('A button full of lanternlight','forgotten','orphanage','Briar House · the cellar','Under the cellar stairs lies a cracked button. At your touch a memory flickers: lanterns, a woman in gray, a green cloak lining. Seven children ride in a wagon. One is carried away separately.','What does the memory actually establish?',['All eight took the same carriage','Seven traveled together; one was separated','The children chose new names'],1,'The memory ends with a scrape beneath a cabinet. Something silver is still hidden in this room.',1),
mission('The first silver shoe','forgotten','orphanage','Briar House · broken cabinet','You lift the cabinet on a wooden wedge. A tiny silver shoe lies beneath it. Its reflection shows a balcony, a closed-eye ring, and Dain in a separate carriage. Its toe turns toward a hollow oak.','Where should you follow the shoe?',['The Hollow Oak in Whispering Woods','The festival kitchen','The market showroom'],0,'The shoe warms in your hands. Beyond the forest stream, a road that was hidden begins to appear.',5),
mission('The road beneath the forest','forest','oak','Hollow Oak · the moonlit stream','At the oak, your shoe glows over the stream. Stepping stones emerge only where moonlight touches the water. The carved sign reads: “Follow the light, not the deepest reflection.”','Choose your crossing.',['Wade into the darkest water','Follow the moonlit stepping stones','Throw away the shoe'],1,'Across the stream stands an elven village, concealed by living branches. The Keeper has been waiting for the memory button.',6),
mission('Three memories, one night','forest','oak','Hidden Village · the Keeper’s house','The Keeper lays out three accounts. The button recalls the gray cloak. The shoe recalls Dain’s carriage. A village witness remembers Lady Ysabet Vale’s closed-eye ring signaling Mistress Vale’s wagon. “No memory sees the whole night,” the Keeper warns.','What connects the accounts?',['A shared signal, wagon and separate transfer','A belief that every stranger is guilty','The color of a random lantern'],0,'Together the accounts point to House Vale. Finren opens a passage to its records chamber. His Silver Last—the village’s shoemaking treasure—is still missing.',6),
mission('Behind Dain’s locked door','forest','oak','House Vale · records chamber','Through the village passage you enter House Vale. A signed transfer ledger names Dain beneath a crossed-out identity. Behind a locked door, a voice remembers river stones. Lady Ysabet’s footsteps approach.','What must you secure before opening the door?',['The signed transfer ledger','Only a guess about his identity','A bag of coins'],0,'With the ledger safe, the second silver shoe turns the lock. Dain hears his own name and chooses to leave with you. You recover Finren’s Silver Last. The footsteps stop at an empty room.',7),
mission('Give the old road back','forest','oak','Hidden Village · Finren’s workshop','Finren touches the empty fitting beneath his shirt. “There is one Silver Last. It belongs to the village.” Dain holds the ledger. The Keeper watches the passage to House Vale.','How do you help everyone leave safely?',['Return the Silver Last to Finren','Sell the Last at the market','Leave Dain in the passage'],0,'Green light runs through Finren’s hands. A safe road opens. Eight siblings are gathering at Elian’s market, but each deserves to speak before anyone decides their future.',6),
mission('Eight voices, eight lives','market','merchant','Elian’s Trading Room · the gathering','All eight siblings have arrived. They share a childhood, but they have built different adult lives. Listen to every voice before proposing a reunion.','Listen to the siblings.',[],null,'The eight voices become a whole song. They agree to meet their parents, carrying the ledger and their right to choose.',8),
mission('The family’s own choice','capital','manor','Silverstitch Manor · the open door','King Aldren and Queen Mirelle wait at an open door. “We never stopped looking,” Mirelle says. Elowen answers: “We want our family back. Our work and friendships belong to us, too.”','How will you help the reunion begin?',['Offer a quiet family supper','Bring their friends to an open-house welcome'],null,'The family crosses the threshold together. No one is asked to surrender the life they built. The ledger still needs a public hearing.',8),
mission('A record that cannot be erased','court','court','Royal Council Chamber · the hearing','Lady Ysabet calls the story a misunderstanding. On the council table lie the signed ledger, the dated register, and the Keeper’s witness account. The magistrate asks you to explain why the case stands.','Which argument establishes the case?',['The strongest accusation wins','The records and independent testimony support one another','A noble title makes evidence unnecessary'],1,'The transfer records are verified. The siblings’ names are restored, and protection is ordered for the other children. The city prepares eight lanterns for a homecoming.',9),
mission('Eight lanterns, a road home','festival','lantern','Lantern Pavilion · the complete song','The festival is alive with light. Maelis sings the line that was missing. Dain sets a river stone beside the eighth lantern. The family waits for you to complete the refrain.','Finish the promise: “We were lost…”',['“…and no one remembered.”','“…but we were not forgotten.”','“…and our story ends in silence.”'],1,'Eight names rise with eight lanterns. The family found its road together. Your choice of welcome becomes part of their new tradition. The city remains yours to explore.',9)
];
function ensure(s){if(!s.silverStory||!Number.isInteger(s.silverStory.step)||s.silverStory.step<0||s.silverStory.step>11)s.silverStory={step:0,spoken:[],rewarded:false};const q=s.silverStory;if(!Array.isArray(q.spoken))q.spoken=[];return q}
function current(s){return missions[ensure(s).step]||null}
function at(s,w){const m=current(s);return !!m&&!!w&&m.district===w.district&&m.room===w.room&&!w.porch}
function finish(s){const q=ensure(s),m=missions[q.step];q.step++;if(q.step===11&&!q.rewarded){s.coins+=150;q.rewarded=true;s.life??={};s.life.bag??={};s.life.bag['eight silver stitches keepsake']=1}return{ok:true,reveal:m.reveal,chapter:m.chapter,complete:q.step===11}}
function answer(s,expected,response,w){const q=ensure(s),m=current(s);if(q.step!==expected||!at(s,w)||!m||q.step===7)return{ok:false,reason:'Follow your current lead at its story location.'};if(globalThis.EldoriaPromiseModel?.active(s)&&Number.isInteger(response)&&response>=0&&response<m.choices.length){const inv=globalThis.EldoriaExperienceModel?.cases[expected];if(inv){const progress=globalThis.EldoriaExperienceModel.progress(s,expected);progress.found=inv.clues.map(v=>v.id);progress.solved=true}if(m.answer!==null)response=m.answer}if(globalThis.EldoriaExperienceModel&&!globalThis.EldoriaExperienceModel.canAdvance(s,expected))return{ok:false,reason:'Search the scene and connect its evidence first.'};if(!Number.isInteger(response)||response<0||response>=m.choices.length)return{ok:false,reason:'Choose an approach.'};if(m.answer!==null&&response!==m.answer)return{ok:false,reason:'Read the scene again. Look for the evidence in the account.'};if(q.step===0){s.clues??=[];if(!s.clues.includes('archive'))s.clues.push('archive')}if(q.step===5)q.estateLedger=true;if(q.step===8)q.welcome=response===0?'quiet supper':'open-house welcome';return finish(s)}
function listen(s,name,w){const q=ensure(s);if(q.step!==7||!at(s,w)||!siblings.includes(name))return{ok:false};if(!q.spoken.includes(name))q.spoken.push(name);return siblings.every(n=>q.spoken.includes(n))?finish(s):{ok:true,next:true}}
globalThis.EldoriaStoryModel={missions,siblings,voices,ensure,current,at,answer,listen};
})();
